export interface ReferrerDetails {
    /**
     * The referrer URL of the installed package.
     */
    referrerUrl: string;
    /**
     * The timestamp in seconds when referrer click happened.
     */
    referrerClickTimestampSeconds: number;
    /**
     * The timestamp in seconds when installation began.
     */
    appInstallTimestampSeconds: number;
    /**
     * The timestamp in seconds when the user first opened the app after installation.
     */
    referrerClickTimestampServerSeconds: number;
    /**
     * The timestamp in seconds when the app installation began from the server's perspective.
     */
    appInstallTimestampServerSeconds: number;
    /**
     * The app's version at the time when the app was first installed.
     */
    installVersion: string;
    /**
     * Whether the instant experience was launched.
     */
    googlePlayInstantParam: boolean;
}
export interface CapacitorReferrerPlugin {
    /**
     * Retrieves the install referrer details from Google Play.
     * Note: This method only works on Android. On iOS/Web, it will reject with an error.
     */
    getReferrerDetails(): Promise<ReferrerDetails>;
}
